    81  otError Tlv::GetValueOffset(const Message &aMessage, uint8_t aType, uint16_t &aValueOffset, uint16_t &aLength)
    82  {
    83      otError  error;
    84      uint16_t offset;
    85      uint16_t size;
    86      bool     isExtendedTlv;
    87
    88      SuccessOrExit(error = Find(aMessage, aType, &offset, &size, &isExtendedTlv));
    89
    90      if (!isExtendedTlv)
    91      {
    92          aValueOffset = offset + sizeof(Tlv);
    93          aLength      = size - sizeof(Tlv);
    94      }
    95      else
    96      {
    97          aValueOffset = offset + sizeof(ExtendedTlv);
    98          aLength      = size - sizeof(ExtendedTlv);
    99      }
   100
   101  exit:
   102      return error;
   103  }
